import{_ as a,o as n,c as i,a5 as e}from"./chunks/framework.Bkm3ODFN.js";const k=JSON.parse('{"title":"📡 GB/T 28181 信令交互全链路","description":"","frontmatter":{},"headers":[],"relativePath":"media/gb28181.md","filePath":"media/gb28181.md","lastUpdated":1794271174000}'),l={name:"media/gb28181.md"};function p(t,s,r,h,d,c){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="📡-gb-t-28181-信令交互全链路" tabindex="-1">📡 GB/T 28181 信令交互全链路 <a class="header-anchor" href="#📡-gb-t-28181-信令交互全链路" aria-label="Permalink to &quot;📡 GB/T 28181 信令交互全链路&quot;">​</a></h1><p>MzMedia 基于 <strong>JAIN-SIP (NIST)</strong> 协议栈实现国标 SIP 信令服务端，支持 UDP 与 TCP 双栈传输。</p><hr><h2 id="_1-注册与-digest-摘要鉴权" tabindex="-1">1. 注册与 Digest 摘要鉴权 <a class="header-anchor" href="#_1-注册与-digest-摘要鉴权" aria-label="Permalink to &quot;1. 注册与 Digest 摘要鉴权&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 摄像机 / NVR (Client)                           MzMedia SIP Server (5060)</span></span>
<span class="line"><span>         │                                                  │</span></span>
<span class="line"><span>         │─────── 1. REGISTER (无认证信息) ─────────────────&gt;│</span></span>
<span class="line"><span>         │                                                  │</span></span>
<span class="line"><span>         │&lt;────── 2. 401 Unauthorized (携带随机 nonce) ─────│</span></span>
<span class="line"><span>         │                                                  │</span></span>
<span class="line"><span>         │─────── 3. REGISTER (携带 MD5 摘要 Response) ─────&gt;│</span></span>
<span class="line"><span>         │                                                  │</span></span>
<span class="line"><span>         │&lt;────── 4. 200 OK (鉴权通过，刷新 Redis 会话) ─────│</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><ul><li><strong>国标 ID 编码规范</strong>：国标统一采用 20 位十进制数字编码，前 10 位为行政区划与行业代码，第 11-13 位代表设备类型： <ul><li><code>132</code>：网络摄像机 (IPC)</li><li><code>131</code>：报警通道</li><li><code>200</code>：网络视频服务器 (NVR/DVR)</li></ul></li><li><strong>密码鉴权</strong>：系统使用 MD5 对 <code>username:domain:password</code> 以及 <code>nonce</code> 进行加盐摘要校验。</li></ul><hr><h2 id="_2-实时点播-invite-与流媒体转发全链路" tabindex="-1">2. 实时点播 (Invite) 与流媒体转发全链路 <a class="header-anchor" href="#_2-实时点播-invite-与流媒体转发全链路" aria-label="Permalink to &quot;2. 实时点播 (Invite) 与流媒体转发全链路&quot;">​</a></h2><p>当 Web 客户端通过 Jessibuca 发起实时视频播放时，信令与媒体流的完整协作拓扑如下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 前端播放器            MzMedia 后端           ZLMediaKit          IPC 摄像机</span></span>
<span class="line"><span>     │                     │                     │                    │</span></span>
<span class="line"><span>     │── 1. 发起点播 ──────&gt;│                     │                    │</span></span>
<span class="line"><span>     │                     │── 2. 申请 RTP 端口 ─&gt;│                    │</span></span>
<span class="line"><span>     │                     │&lt;─ 3. 返回端口/SSRC ──│                    │</span></span>
<span class="line"><span>     │                     │                                          │</span></span>
<span class="line"><span>     │                     │─────── 4. SIP INVITE (带 SDP) ──────────&gt;│</span></span>
<span class="line"><span>     │                     │&lt;────── 5. 200 OK (带设备 SDP) ───────────│</span></span>
<span class="line"><span>     │                     │─────── 6. ACK ──────────────────────────&gt;│</span></span>
<span class="line"><span>     │                     │                                          │</span></span>
<span class="line"><span>     │                     │                     │&lt;── 7. 推送 RTP 流 ─│</span></span>
<span class="line"><span>     │&lt;── 8. WebRTC/FLV ───│─────────────────────│                    │</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><ol><li><strong>信令准备</strong>：后端向 ZLMediaKit 发起 REST Hook，动态开放单个 RTP 接收端口（如 <code>30000</code>）并生成专属 SSRC；</li><li><strong>SDP 媒体协商</strong>：向摄像机发送 <code>INVITE</code>，携带 ZLMediaKit 的接收 IP、端口与媒体编码要求；</li><li><strong>推流与转封装</strong>：设备向该端口发送封装有 PS (Program Stream) 的 RTP 包，ZLMediaKit 实时解复用并转换为 WebRTC、WS-FLV、HLS 格式输出。</li></ol><hr><h2 id="_3-心跳保活-keepalive" tabindex="-1">3. 心跳保活 (Keepalive) <a class="header-anchor" href="#_3-心跳保活-keepalive" aria-label="Permalink to &quot;3. 心跳保活 (Keepalive)&quot;">​</a></h2><ul><li>摄像机根据配置的周期（默认 30~60 秒）发送 SIP <code>MESSAGE</code> 请求：<div class="language-xml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;?</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xml</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> encoding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GB2312&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Notify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">CmdType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Keepalive&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">CmdType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">SN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;12345&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">SN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DeviceID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;34020000001320000001&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DeviceID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;OK&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Notify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div></li><li>服务端解析后刷新 <code>wvp_device</code> 中的 <code>keepalive_time</code> 并回送 <code>200 OK</code>；超时未收到心跳将被标记为离线。</li></ul><hr><h2 id="_4-设备通道目录检索-catalog" tabindex="-1">4. 设备通道目录检索 (Catalog) <a class="header-anchor" href="#_4-设备通道目录检索-catalog" aria-label="Permalink to &quot;4. 设备通道目录检索 (Catalog)&quot;">​</a></h2><ul><li>平台主动下发 <code>Catalog</code> 查询，支持大通道设备（如 64 路 NVR）分包拉取；</li><li>接收到设备响应后，自动更新 <code>wvp_device_channel</code> 物理通道与逻辑子通道拓扑。</li></ul>`,17)])])}const E=a(l,[["render",p]]);export{k as __pageData,E as default};
